48			{"empty omits permission flags", "", nil, "--permission-mode"},
49		}
50	
51		for _, tt := range tests {
52			t.Run(tt.name, func(t *testing.T) {
53				p := &Plugin{resolvedBinary: "claude"}
54				cmd, err := p.GetLaunchCommand(context.Background(), ports.LaunchConfig{
55					Permissions: tt.permission,
56				})
57				if err != nil {
58					t.Fatal(err)
59				}
