158	func TestGetAgentHooksInstallsClaudeHooks(t *testing.T) {
159		p := &Plugin{resolvedBinary: "claude"}
160		workspace := t.TempDir()
161		settingsDir := filepath.Join(workspace, ".claude")
162		if err := os.MkdirAll(settingsDir, 0o755); err != nil {
163			t.Fatal(err)
164		}
165		settingsPath := filepath.Join(settingsDir, "settings.local.json")
166		// Pre-seed a user's own Stop hook + an unrelated setting; both must survive.
167		existing := `{"hooks":{"Stop":[{"hooks":[{"type":"command","command":"my own stop hook","timeout":5}]}]},"permissions":{"defaultMode":"plan"}}`
168		if err := os.WriteFile(settingsPath, []byte(existing), 0o644); err != nil {
169			t.Fatal(err)
170		}
171	
172		cfg := ports.WorkspaceHookConfig{DataDir: t.TempDir(), SessionID: "sess-1", WorkspacePath: workspace}
173		if err := p.GetAgentHooks(context.Background(), cfg); err != nil {
174			t.Fatal(err)
175		}
176		// A second install must not duplicate AO hook commands.
177		if err := p.GetAgentHooks(context.Background(), cfg); err != nil {
178			t.Fatal(err)
179		}
180	
181		data, err := os.ReadFile(settingsPath)
182		if err != nil {
183			t.Fatal(err)
184		}
185		var config struct {
186			Hooks       map[string][]claudeMatcherGroup `json:"hooks"`
187			Permissions json.RawMessage                 `json:"permissions"`
188		}
189		if err := json.Unmarshal(data, &config); err != nil {
190			t.Fatal(err)
191		}
192		if config.Hooks == nil {
193			t.Fatalf("hooks object missing: %s", data)
194		}
195	
196		// Every managed command is installed exactly once under its event.
197		for _, spec := range claudeManagedHooks {
198			if got := countClaudeHookCommand(config.Hooks[spec.Event], spec.Command); got != 1 {
199				t.Fatalf("%s command %q count = %d, want 1", spec.Event, spec.Command, got)
200			}
201		}
202		// Existing user hook preserved.
203		if countClaudeHookCommand(config.Hooks["Stop"], "my own stop hook") != 1 {
204			t.Fatalf("existing Stop hook not preserved: %#v", config.Hooks["Stop"])
205		}
206		// Unrelated settings preserved.
207		if len(config.Permissions) == 0 {
208			t.Fatalf("unrelated settings clobbered: %s", data)
209		}
210		// SessionStart carries the required matcher; UserPromptSubmit omits it.
211		if m := matcherForCommand(config.Hooks["SessionStart"], "ao hooks claude-code session-start"); m == nil || *m != "startup" {
212			t.Fatalf("SessionStart matcher = %v, want startup", m)
213		}
214		if m := matcherForCommand(config.Hooks["UserPromptSubmit"], "ao hooks claude-code user-prompt-submit"); m != nil {
215			t.Fatalf("UserPromptSubmit matcher = %v, want none", m)
216		}
217		// Notification and SessionEnd install with no matcher (they fire for all
218		// sub-types; the handler filters on the payload).
219		if m := matcherForCommand(config.Hooks["Notification"], "ao hooks claude-code notification"); m != nil {
220			t.Fatalf("Notification matcher = %v, want none", m)
221		}
222		if m := matcherForCommand(config.Hooks["SessionEnd"], "ao hooks claude-code session-end"); m != nil {
223			t.Fatalf("SessionEnd matcher = %v, want none", m)
224		}
225	}
