530	func containsSubsequence(values, needle []string) bool {
531		if len(needle) == 0 {
532			return true
533		}
534		for start := 0; start+len(needle) <= len(values); start++ {
535			ok := true
536			for i, w := range needle {
537				if values[start+i] != w {
538					ok = false
539					break
540				}
541			}
542			if ok {
543				return true
544			}
545		}
