package conformance

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/registry"
)

// strict reports whether the suite should enforce (fail CI on Fail/Gap and on
// golden drift). Default is report-only: the matrix is the deliverable, and the
// adapters are under active development, so the suite surfaces findings without
// turning CI red until a dedicated job opts in with AOEVAL_STRICT=1.
func strict() bool { return os.Getenv("AOEVAL_STRICT") == "1" }

// TestConformance runs every registered adapter through all six dimensions.
// Each (harness, dimension) is its own subtest, so a single cell is runnable
// with: go test ./... -run 'TestConformance/claude-code/hooks' -v
// The full matrix is rendered at the end.
func TestConformance(t *testing.T) {
	ctx := context.Background()
	harnessed := registry.Harnessed()
	if len(harnessed) == 0 {
		t.Fatal("registry.Harnessed() returned no adapters")
	}

	var all []Result
	for _, ha := range harnessed {
		t.Run(string(ha.Harness), func(t *testing.T) {
			for _, res := range Run(ctx, ha) {
				all = append(all, res)
				t.Run(res.Dimension, func(t *testing.T) {
					logResult(t, res)
					if strict() && (res.Status == StatusFail || res.Status == StatusGap) {
						t.Errorf("%s/%s = %s: %s", res.Harness, res.Dimension, res.Status, res.Detail)
					}
				})
			}
		})
	}

	renderMatrix(t, harnessed, all)
}

// TestGoldenCommands snapshots every adapter's exact launch and restore argv to
// testdata/golden/<harness>.txt — the artifact a human reviews against each
// agent's real CLI docs (dimension #6) and the guard that catches silent argv
// drift. Regenerate with: AOEVAL_UPDATE_GOLDEN=1 go test ./... -run TestGoldenCommands
func TestGoldenCommands(t *testing.T) {
	ctx := context.Background()
	update := os.Getenv("AOEVAL_UPDATE_GOLDEN") == "1"
	dir := filepath.Join("testdata", "golden")
	if update {
		if err := os.MkdirAll(dir, 0o750); err != nil {
			t.Fatal(err)
		}
	}

	for _, ha := range registry.Harnessed() {
		t.Run(string(ha.Harness), func(t *testing.T) {
			lines, err := CommandEvidence(ctx, ha)
			if err != nil {
				report(t, "CommandEvidence: %v", err)
				return
			}
			got := strings.Join(lines, "\n") + "\n"
			path := filepath.Join(dir, string(ha.Harness)+".txt")

			if update {
				if err := os.WriteFile(path, []byte(got), 0o600); err != nil {
					t.Fatal(err)
				}
				t.Logf("wrote %s", path)
				return
			}

			want, err := os.ReadFile(path) //nolint:gosec // path built from a fixed harness id
			if err != nil {
				t.Logf("no golden for %s (run AOEVAL_UPDATE_GOLDEN=1 to create). got:\n%s", ha.Harness, got)
				return
			}
			if string(want) != got {
				report(t, "command drift:\n--- want ---\n%s--- got ---\n%s", want, got)
			}
		})
	}
}

// report logs in report-only mode and errors under AOEVAL_STRICT.
func report(t *testing.T, format string, args ...any) {
	t.Helper()
	if strict() {
		t.Errorf(format, args...)
		return
	}
	t.Logf("(report-only) "+format, args...)
}

func logResult(t *testing.T, r Result) {
	t.Helper()
	t.Logf("%-6s %s", strings.ToUpper(string(r.Status)), r.Detail)
	for _, e := range r.Evidence {
		t.Logf("        %s", e)
	}
}

// renderMatrix prints the adapters × dimensions grid plus a legend, so the test
// log itself is a paste-ready eval matrix.
func renderMatrix(t *testing.T, harnessed []registry.HarnessAgent, all []Result) {
	t.Helper()

	cell := map[string]map[string]Status{}
	for _, r := range all {
		if cell[r.Harness] == nil {
			cell[r.Harness] = map[string]Status{}
		}
		cell[r.Harness][r.Dimension] = r.Status
	}

	glyph := map[Status]string{
		StatusPass: "ok ",
		StatusFail: "FAIL",
		StatusGap:  "GAP",
		StatusSkip: "—  ",
	}

	var b strings.Builder
	b.WriteString("\n")
	fmt.Fprintf(&b, "%-14s", "HARNESS")
	for _, d := range Dimensions {
		fmt.Fprintf(&b, " %-12s", strings.ToUpper(d))
	}
	b.WriteString("\n")
	for _, ha := range harnessed {
		h := string(ha.Harness)
		fmt.Fprintf(&b, "%-14s", h)
		for _, d := range Dimensions {
			fmt.Fprintf(&b, " %-12s", glyph[cell[h][d]])
		}
		b.WriteString("\n")
	}
	b.WriteString("\nlegend: ok=pass  FAIL=contract violation  GAP=wired-but-broken  —=n/a (limitation)\n")

	// Summary counts.
	counts := map[Status]int{}
	for _, r := range all {
		counts[r.Status]++
	}
	fmt.Fprintf(&b, "totals: %d pass, %d fail, %d gap, %d skip across %d adapters\n",
		counts[StatusPass], counts[StatusFail], counts[StatusGap], counts[StatusSkip], len(harnessed))

	t.Log(b.String())

	if os.Getenv("AOEVAL_UPDATE_GOLDEN") == "1" {
		if err := os.WriteFile(filepath.Join("testdata", "matrix.txt"), []byte(b.String()), 0o600); err != nil {
			t.Logf("could not write testdata/matrix.txt: %v", err)
		}
	}
}

