// normalizeArgv replaces argv[0] (which may be an absolute, machine-specific
// binary path resolved off PATH) with its basename, so evidence and golden
// snapshots are stable across machines.
func normalizeArgv(cmd []string) []string {
	if len(cmd) == 0 {
		return cmd
	}
	out := append([]string(nil), cmd...)
	out[0] = filepath.Base(out[0])
	return out
}

input.new_string:
// normalizeArgv rewrites a command so evidence and golden snapshots are stable
// across runs and machines:
//   - the per-run eval workspace path becomes <workspace>,
//   - any other path under the OS temp dir becomes <tmp>/…,
//   - any remaining absolute path (a machine-specific resolved binary, e.g.
//     /Users/me/.local/bin/goose or a Nix profile path) becomes its basename.
//
// Argument values that legitimately carry a path (a worktree --cwd, a temp
// settings file) are stabilized by the first two rules before the basename
// rule sees them, so only real binary paths get shortened.
func normalizeArgv(cmd []string, ws string) []string {
	if len(cmd) == 0 {
		return cmd
	}
	tmp := strings.TrimRight(os.TempDir(), "/")
	out := make([]string, len(cmd))
	for i, tok := range cmd {
		t := tok
		if ws != "" {
			t = strings.ReplaceAll(t, ws, "<workspace>")
		}
		if tmp != "" {
			t = strings.ReplaceAll(t, tmp, "<tmp>")
		}
		if filepath.IsAbs(t) {
			t = filepath.Base(t)
		}
		out[i] = t
	}
	return out
}

