	dto liveSessionDTO
	err error
}

type livePollTickMsg struct{ id string }

// --- behavior ---

// startLive spawns the selected adapter as a real session and begins polling,
// or logs why it can't (live disabled, or the agent's binary isn't installed).
func (m *Model) startLive() tea.Cmd {
	ha := m.harnessed[m.row]
	h := string(ha.Harness)

	if !m.live.enabled() {
		m.appendLog("live: needs --project <id> and a running daemon (ao start)")
		return nil
	}
	if !m.capable(ha) {
		m.appendLog(fmt.Sprintf("live: %s binary not installed — deterministic only", h))
		return nil
	}

	m.appendLog(fmt.Sprintf("live: spawning %s …", h))
	_ = m.stage.Run(context.Background(),
		fmt.Sprintf("# live: ao spawn --project %s --harness %s", m.live.ProjectID, h))

	client := m.live.Client
	req := liveSpawnRequest{ProjectID: m.live.ProjectID, Harness: h, Prompt: m.live.Prompt}
	return func() tea.Msg {
		var res liveSpawnResponse
		err := client.Post(context.Background(), "sessions", req, &res)
		return liveSpawnResultMsg{harness: h, id: res.Session.ID, status: res.Session.Status, err: err}
	}
}

// pollCmd reads the live session's current state once.
func (m *Model) pollCmd(id string) tea.Cmd {
	client := m.live.Client
	return func() tea.Msg {
		var res liveSessionResponse
		err := client.Get(context.Background(), "sessions/"+url.PathEscape(id), &res)
		return livePollResultMsg{id: id, dto: res.Session, err: err}
	}
}

// applyLiveSpawn handles the spawn result and kicks off polling.
func (m *Model) applyLiveSpawn(msg liveSpawnResultMsg) tea.Cmd {
	if msg.err != nil {
		m.appendLog(fmt.Sprintf("live: spawn %s failed: %v", msg.harness, msg.err))
		m.liveSession = nil
		return nil
	}
	m.liveSession = &liveSession{id: msg.id, harness: msg.harness, status: msg.status, state: "…"}
	m.appendLog(fmt.Sprintf("live: %s spawned as %s", msg.harness, msg.id))
	return m.pollCmd(msg.id)
}

// applyLivePoll updates the live session and schedules the next poll until the
// session terminates or errors.
func (m *Model) applyLivePoll(msg livePollResultMsg) tea.Cmd {
	if m.liveSession == nil || m.liveSession.id != msg.id {
		return nil // a stale poll for a session the presenter already cleared.
	}
	if msg.err != nil {
		m.liveSession.errText = msg.err.Error()
		return nil
	}
	ls := m.liveSession
	if msg.dto.State() != "" && msg.dto.State() != ls.state {
		ls.history = append(ls.history, msg.dto.State())
		if len(ls.history) > 8 {
			ls.history = ls.history[len(ls.history)-8:]
		}
	}
	ls.state = msg.dto.State()
	ls.displayName = msg.dto.DisplayName
	ls.status = msg.dto.Status
	ls.terminated = msg.dto.IsTerminated
	if ls.terminated || ls.state == string(ports.PermissionModeDefault) /*never*/ {
		return nil
	}
	if ls.terminated {
		return nil
	}
	id := ls.id
	return tea.Tick(pollInterval, func(time.Time) tea.Msg { return livePollTickMsg{id: id} })
}

// State returns the activity state, defaulting to empty.
func (d liveSessionDTO) State() string { return d.Activity.State }

// capable reports (and caches) whether an adapter's native binary is installed,
// so live spawn isn't offered for an agent that can't run here.
func (m *Model) capable(ha registry.HarnessAgent) bool {
	h := string(ha.Harness)
	if v, ok := m.liveCap[h]; ok {
		return v
	}
	v := binaryInstalled(context.Background(), ha)
	m.liveCap[h] = v
	return v
}

// binaryInstalled builds the adapter's launch command and checks whether its
// resolved binary exists — reusing GetLaunchCommand so the check needs no
// per-adapter knowledge of the binary name.
func binaryInstalled(ctx context.Context, ha registry.HarnessAgent) bool {
	ws, err := os.MkdirTemp("", "aoeval-live-")
	if err != nil {
		return false
	}
	defer func() { _ = os.RemoveAll(ws) }()

	cmd, err := ha.Agent.GetLaunchCommand(ctx, ports.LaunchConfig{
		Permissions:   ports.PermissionModeDefault,
		Prompt:        "x",
		SessionID:     "x",
		WorkspacePath: ws,
	})
	if err != nil || len(cmd) == 0 {
		return false
	}
	bin := cmd[0]
	if filepath.IsAbs(bin) {
		info, err := os.Stat(bin)
		return err == nil && !info.IsDir()
	}
	_, err = exec.LookPath(bin)
	return err == nil
}

// Package evalrig is the interactive control deck of the AO Adapter Proving
// Ground: a Bubble Tea TUI that renders the adapters × six-dimensions eval
// matrix and lets a presenter run cells one keypress at a time, driving a
// sibling Zellij "stage" pane to show each check executing live. The verdicts
// come from the same in-process conformance engine CI runs, so the demo and the
// regression guard can never disagree.
package evalrig

import (
	"context"
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/conformance"
	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/registry"
)

type cellState int

const (
	cellPending cellState = iota
	cellRunning
	cellDone
)

// Model is the control-deck state.
type Model struct {
	harnessed []registry.HarnessAgent
	dims      []string
	state     map[string]map[string]cellState
	result    map[string]map[string]conformance.Result
	row, col  int
	logs      []string
	stage     *Stage
	width     int
	quitting  bool
}

// cellResultMsg carries a finished cell verdict back into Update.
type cellResultMsg struct {
	harness string
	dim     string
	result  conformance.Result
}

// New builds the deck over the registered adapters and a (possibly no-op) stage.
func New(stage *Stage) Model {
	harnessed := registry.Harnessed()
	state := make(map[string]map[string]cellState, len(harnessed))
	result := make(map[string]map[string]conformance.Result, len(harnessed))
	for _, ha := range harnessed {
		h := string(ha.Harness)
		state[h] = map[string]cellState{}
		result[h] = map[string]conformance.Result{}
		for _, d := range conformance.Dimensions {
			state[h][d] = cellPending
		}
	}
	return Model{
		harnessed: harnessed,
		dims:      conformance.Dimensions,
		state:     state,
		result:    result,
		stage:     stage,
	}
}

// Init implements tea.Model.
func (m Model) Init() tea.Cmd { return nil }

// Update implements tea.Model.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		return m, nil

	case cellResultMsg:
		m.state[msg.harness][msg.dim] = cellDone
		m.result[msg.harness][msg.dim] = msg.result
		m.appendLog(fmt.Sprintf("%s/%s → %s", msg.harness, msg.dim, strings.ToUpper(string(msg.result.Status))))
		return m, nil

	case tea.KeyMsg:
		return m.handleKey(msg)
	}
	return m, nil
}

func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "q", "ctrl+c", "esc":
		m.quitting = true
		return m, tea.Quit
	case "up", "k":
		m.row = clamp(m.row-1, len(m.harnessed)-1)
	case "down", "j":
		m.row = clamp(m.row+1, len(m.harnessed)-1)
	case "left", "h":
		m.col = clamp(m.col-1, len(m.dims)-1)
	case "right", "l":
		m.col = clamp(m.col+1, len(m.dims)-1)
	case "enter":
		// Run the selected cell, then advance to the next — the "keep pressing
		// enter to run the next test" presenter flow.
		cmd := m.runSelected()
		m.advance()
		return m, cmd
	case " ", "r":
		// Re-run the selected cell in place (no cursor advance).
		cmd := m.runSelected()
		return m, cmd
	case "a":
		// Run every dimension for the current adapter.
		cmd := m.runRow(m.row)
		return m, cmd
	case "A":
		// Run the whole matrix.
		cmd := m.runAll()
		return m, cmd
	}
	return m, nil
}

func (m *Model) runSelected() tea.Cmd {
	return m.runCell(m.row, m.col)
}

func (m *Model) runCell(row, col int) tea.Cmd {
	ha := m.harnessed[row]
	h := string(ha.Harness)
	dim := m.dims[col]
	if m.state[h][dim] == cellRunning {
		return nil
	}
	m.state[h][dim] = cellRunning
	m.appendLog(fmt.Sprintf("running %s/%s …", h, dim))
	stage := m.stage
	return func() tea.Msg {
		ctx := context.Background()
		// Show the real test executing on stage (best effort), then compute the
		// authoritative verdict in-process.
		_ = stage.Run(ctx, goTestCommand(h, dim))
		res, _ := conformance.RunDimension(ctx, ha, dim)
		return cellResultMsg{harness: h, dim: dim, result: res}
	}
}

func (m *Model) runRow(row int) tea.Cmd {
	cmds := make([]tea.Cmd, 0, len(m.dims))
	for c := range m.dims {
		if cmd := m.runCell(row, c); cmd != nil {
			cmds = append(cmds, cmd)
		}
	}
	return tea.Batch(cmds...)
}

func (m *Model) runAll() tea.Cmd {
	cmds := make([]tea.Cmd, 0, len(m.harnessed)*len(m.dims))
	for r := range m.harnessed {
		for c := range m.dims {
			if cmd := m.runCell(r, c); cmd != nil {
				cmds = append(cmds, cmd)
			}
		}
	}
	return tea.Batch(cmds...)
}

// advance moves the cursor to the next cell, left-to-right then down a row.
func (m *Model) advance() {
	m.col++
	if m.col >= len(m.dims) {
		m.col = 0
		if m.row < len(m.harnessed)-1 {
			m.row++
		} else {
			m.col = len(m.dims) - 1 // stay on the last cell
		}
	}
}

func (m *Model) appendLog(line string) {
	m.logs = append(m.logs, line)
	if len(m.logs) > 6 {
		m.logs = m.logs[len(m.logs)-6:]
	}
}

// goTestCommand is the command the stage runs to demonstrate one cell: the real
// conformance subtest, in verbose mode, so the audience sees genuine PASS lines.
func goTestCommand(harness, dim string) string {
	return fmt.Sprintf(
		"go test ./internal/adapters/agent/conformance/ -run 'TestConformance/%s/%s' -v -count=1",
		harness, dim,
	)
}

// clamp bounds v to [0, hi]; the cursor never goes below the first row/column.
func clamp(v, hi int) int {
	if v < 0 {
		return 0
	}
	if v > hi {
		return hi
	}
	return v
}

