package evalrig

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"sync"
	"testing"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/conformance"
)

// fakeZellij records the args of every zellij invocation and answers list-panes
// with a fixed JSON payload.
type fakeZellij struct {
	listJSON string
	calls    [][]string
}

func (f *fakeZellij) run(_ context.Context, args ...string) ([]byte, error) {
	f.calls = append(f.calls, args)
	if len(args) >= 4 && args[3] == "list-panes" {
		return []byte(f.listJSON), nil
	}
	return nil, nil
}

func TestStageDiscoversPaneByTitle(t *testing.T) {
	f := &fakeZellij{listJSON: `[
		{"id":0,"is_plugin":false,"title":"deck"},
		{"id":1,"is_plugin":true,"title":"stage"},
		{"id":2,"is_plugin":false,"title":"stage"}
	]`}
	s := newStage(context.Background(), "sess-1", f.run)
	if !s.Available() {
		t.Fatalf("Available() = false, want true")
	}
	// The non-plugin "stage" pane (id 2) wins over the plugin one (id 1).
	if s.PaneID() != "terminal_2" {
		t.Fatalf("PaneID() = %q, want terminal_2", s.PaneID())
	}

	if err := s.Run(context.Background(), "go test ./..."); err != nil {
		t.Fatalf("Run: %v", err)
	}
	// Last two calls must be a paste of the command, then an Enter, both
	// targeting the discovered pane id.
	paste := s.lastCallWith(f, "paste")
	if paste == nil || paste[len(paste)-1] != "go test ./..." {
		t.Fatalf("paste call = %v", paste)
	}
	if !slices.Contains(paste, "--pane-id") || !slices.Contains(paste, "terminal_2") {
		t.Fatalf("paste did not target the stage pane: %v", paste)
	}
	enter := s.lastCallWith(f, "send-keys")
	if enter == nil || enter[len(enter)-1] != "Enter" {
		t.Fatalf("send-keys call = %v", enter)
	}
}

func TestStageFallsBackToNonDeckPane(t *testing.T) {
	// No pane titled "stage": fall back to the first non-plugin, non-deck pane.
	f := &fakeZellij{listJSON: `[
		{"id":0,"is_plugin":false,"title":"deck"},
		{"id":7,"is_plugin":false,"title":"scratch"}
	]`}
	s := newStage(context.Background(), "sess-1", f.run)
	if s.PaneID() != "terminal_7" {
		t.Fatalf("PaneID() = %q, want terminal_7 (fallback)", s.PaneID())
	}
}

// TestStageSerializesConcurrentWrites pins the fix for the garbled-stage bug:
// the deck runs each cell's check in its own goroutine, so without serialization
// concurrent paste+enter pairs interleave and commands land mashed on one line
// (…-count=1go test…). Every paste must be immediately followed by its Enter.
func TestStageSerializesConcurrentWrites(t *testing.T) {
	f := &fakeZellij{}
	s := &Stage{session: "s", paneID: "terminal_1", run: f.run}

	var wg sync.WaitGroup
	for i := 0; i < 16; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			_ = s.Run(context.Background(), fmt.Sprintf("cmd-%d", i))
		}(i)
	}
	wg.Wait()

	if len(f.calls) != 32 {
		t.Fatalf("expected 32 calls (16 paste+enter pairs), got %d", len(f.calls))
	}
	for i := 0; i < len(f.calls); i += 2 {
		paste, enter := f.calls[i], f.calls[i+1]
		if len(paste) < 4 || paste[3] != "paste" {
			t.Fatalf("call %d is not a paste: %v", i, paste)
		}
		if len(enter) < 4 || enter[3] != "send-keys" || enter[len(enter)-1] != "Enter" {
			t.Fatalf("call %d is not the Enter for its paste: %v", i+1, enter)
		}
	}
}

func TestStageNoopWithoutSession(t *testing.T) {
	f := &fakeZellij{}
	s := newStage(context.Background(), "", f.run)
	if s.Available() {
		t.Fatalf("Available() = true without a session")
	}
	if err := s.Run(context.Background(), "echo hi"); err != nil {
		t.Fatalf("Run no-op: %v", err)
	}
	if len(f.calls) != 0 {
		t.Fatalf("expected no zellij calls without a session, got %v", f.calls)
	}
}

func (s *Stage) lastCallWith(f *fakeZellij, action string) []string {
	var found []string
	for _, c := range f.calls {
		if len(c) >= 4 && c[3] == action {
			found = c
		}
	}
	return found
}

// noopStage is a Stage that is never "available", so the deck runs matrix-only.
func noopStage() *Stage { return &Stage{} }

func TestModelRunCellComputesVerdict(t *testing.T) {
	m := New(noopStage(), LiveConfig{})
	if len(m.harnessed) == 0 {
		t.Fatal("no adapters")
	}
	// Default cursor is the first adapter / first dimension (spawn). Pressing
	// enter runs that cell and advances the cursor.
	updated, cmd := m.Update(tea.KeyMsg{Type: tea.KeyEnter})
	m = updated.(Model)
	if cmd == nil {
		t.Fatal("enter produced no command")
	}
	h := string(m.harnessed[0].Harness)
	if m.state[h][conformance.DimSpawn] != cellRunning {
		t.Fatalf("selected cell state = %v, want running", m.state[h][conformance.DimSpawn])
	}
	if m.col != 1 {
		t.Fatalf("cursor did not advance: col = %d, want 1", m.col)
	}

	// Execute the command to get the verdict, then feed it back.
	msg := cmd()
	res, ok := msg.(cellResultMsg)
	if !ok {
		t.Fatalf("command returned %T, want cellResultMsg", msg)
	}
	updated, _ = m.Update(res)
	m = updated.(Model)
	if m.state[h][conformance.DimSpawn] != cellDone {
		t.Fatalf("cell state after result = %v, want done", m.state[h][conformance.DimSpawn])
	}
	if got := m.result[h][conformance.DimSpawn].Status; got != conformance.StatusPass {
		t.Fatalf("spawn verdict = %q, want pass", got)
	}
}

func TestModelNavigationClamps(t *testing.T) {
	m := New(noopStage(), LiveConfig{})
	// Up/left at the origin must not go negative.
	up, _ := m.Update(tea.KeyMsg{Type: tea.KeyUp})
	left, _ := up.(Model).Update(tea.KeyMsg{Type: tea.KeyLeft})
	m = left.(Model)
	if m.row != 0 || m.col != 0 {
		t.Fatalf("clamp failed: row=%d col=%d", m.row, m.col)
	}
}

func TestModelViewRenders(t *testing.T) {
	m := New(noopStage(), LiveConfig{})
	out := m.View()
	for _, want := range []string{"AO Adapter Proving Ground", "HARNESS", "SPAWN", string(m.harnessed[0].Harness), "matrix-only"} {
		if !strings.Contains(stripANSI(out), want) {
			t.Fatalf("view missing %q\n---\n%s", want, stripANSI(out))
		}
	}
}

// fakeDaemon implements DaemonClient: it answers spawn with a fixed id and
// returns a scripted sequence of activity states on each poll.
type fakeDaemon struct {
	id     string
	states []string
	polls  int
}

func (f *fakeDaemon) Post(_ context.Context, _ string, _, out any) error {
	resp := out.(*liveSpawnResponse)
	resp.Session.ID = f.id
	resp.Session.Status = "ok"
	return nil
}

func (f *fakeDaemon) Get(_ context.Context, _ string, out any) error {
	resp := out.(*liveSessionResponse)
	i := f.polls
	if i >= len(f.states) {
		i = len(f.states) - 1
	}
	resp.Session.ID = f.id
	resp.Session.DisplayName = "Fix the thing"
	resp.Session.Activity.State = f.states[i]
	resp.Session.IsTerminated = f.states[i] == "exited"
	f.polls++
	return nil
}

func TestLiveSpawnAndPoll(t *testing.T) {
	f := &fakeDaemon{id: "sess-live-1", states: []string{"active", "exited"}}
	m := New(noopStage(), LiveConfig{Client: f, ProjectID: "proj-1", Prompt: "do it"})
	h := string(m.harnessed[0].Harness)
	m.liveCap[h] = true // force live-capable so the test doesn't depend on an installed binary

	// L spawns.
	updated, cmd := m.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune("L")})
	m = updated.(Model)
	if cmd == nil {
		t.Fatal("L produced no spawn command")
	}
	spawn, ok := cmd().(liveSpawnResultMsg)
	if !ok || spawn.id != "sess-live-1" {
		t.Fatalf("spawn result = %+v", spawn)
	}

	// Applying the spawn starts polling.
	updated, cmd = m.Update(spawn)
	m = updated.(Model)
	if m.liveSession == nil || m.liveSession.id != "sess-live-1" {
		t.Fatalf("liveSession = %+v", m.liveSession)
	}
	poll1 := cmd().(livePollResultMsg)
	updated, cmd = m.Update(poll1)
	m = updated.(Model)
	if m.liveSession.state != "active" || m.liveSession.displayName != "Fix the thing" {
		t.Fatalf("after poll: state=%q name=%q", m.liveSession.state, m.liveSession.displayName)
	}
	if cmd == nil {
		t.Fatal("active session should schedule another poll")
	}
	if !strings.Contains(stripANSI(m.View()), "sess-live-1") {
		t.Fatalf("live panel missing session id:\n%s", stripANSI(m.View()))
	}

	// Next poll reports exited → terminated, no further polling scheduled.
	poll2 := m.pollCmd("sess-live-1")().(livePollResultMsg)
	updated, cmd = m.Update(poll2)
	m = updated.(Model)
	if !m.liveSession.terminated {
		t.Fatalf("session should be terminated, got %+v", m.liveSession)
	}
	if cmd != nil {
		t.Fatal("terminated session should not schedule another poll")
	}
}

