20	// The session view: a focused overlay split into a resizable left info pane and
21	// a right "canvas" that hosts the terminal. Owns the session's data fetch and
22	// the kill/restore/rename/send actions (formerly the detail drawer).
23	export function SessionView(props: {
24	  sessionId: string;
25	  fallback: Session | null;
26	  projects: ProjectSummary[];
27	  onClose: () => void;
28	  onChanged: () => Promise<void> | void;
29	  onError: (msg: string) => void;
30	}) {
31	  const [session, setSession] = useState<Session | null>(props.fallback);
32	  const [message, setMessage] = useState("");
33	  const [busy, setBusy] = useState<string | null>(null);
34	  const [renaming, setRenaming] = useState(false);
35	  const [nameDraft, setNameDraft] = useState("");
36	
37	  const refresh = useCallback(async () => {
38	    try {
39	      setSession(await getSession(props.sessionId));
40	    } catch (err) {
41	      props.onError(err instanceof Error ? err.message : String(err));
42	    }
43	  }, [props]);
44	
45	  useEffect(() => {
46	    void refresh();
47	    const id = window.setInterval(() => void refresh(), 2000);
48	    return () => window.clearInterval(id);
49	  }, [refresh]);
50	
51	  useEffect(() => {
52	    const onKey = (e: KeyboardEvent) => e.key === "Escape" && props.onClose();
53	    window.addEventListener("keydown", onKey);
54	    return () => window.removeEventListener("keydown", onKey);
