	envelope.WriteJSON(w, http.StatusOK, AnnotationResponse{OK: true, SessionID: sessionID(r), Delivered: message})
}

// formatAnnotation renders a captured UI annotation into a concise instruction
// for the agent. It leads with the grep-able selector/classes so the agent can
// locate the element in source, and ends with the user's request.
func formatAnnotation(a AnnotationRequest) string {
	var b strings.Builder
	b.WriteString("[ui-annotation] The user pointed at an element in the live preview")
	if u := strings.TrimSpace(a.URL); u != "" {
		b.WriteString(" (")
		b.WriteString(u)
		b.WriteString(")")
	}
	b.WriteString(":\n")
	if e := strings.TrimSpace(a.Element); e != "" {
		b.WriteString("  element:  ")
		b.WriteString(e)
		b.WriteString("\n")
	}
	b.WriteString("  selector: ")
	b.WriteString(strings.TrimSpace(a.Selector))
	b.WriteString("\n")
	if t := strings.TrimSpace(a.Text); t != "" {
		b.WriteString("  text:     \"")
		b.WriteString(clampRunes(t, 200))
		b.WriteString("\"\n")
	}
	if s := strings.TrimSpace(a.Source); s != "" {
		b.WriteString("  source:   ")
		b.WriteString(s)
		b.WriteString("\n")
	}
	if note := strings.TrimSpace(a.Note); note != "" {
		b.WriteString("  request:  ")
		b.WriteString(note)
		b.WriteString("\n")
	}
	b.WriteString("Locate this element in the code (grep the selector/classes) and address the request above.")
	return b.String()
}

func clampRunes(s string, maxRunes int) string {
	r := []rune(s)
	if len(r) <= maxRunes {
		return s
	}
	return string(r[:maxRunes]) + "…"
}

