package controllers_test

import (
	"net/http"
	"strings"
	"testing"
)

// TestSessionsAPI_AnnotationDeliversToAgent proves the in-app browser annotation
// path: a captured UI element POSTed to the session is formatted into an
// agent-readable instruction and delivered through the same Send chain that
// `ao send` uses — so the agent in the terminal receives it as context.
func TestSessionsAPI_AnnotationDeliversToAgent(t *testing.T) {
	svc := newFakeSessionService()
	srv := newSessionTestServer(t, svc)

	payload := `{"selector":"button.btn.primary","url":"http://localhost:5173/","element":"button.btn.primary","text":"Save changes","note":"make this button red"}`
	body, status, _ := doRequest(t, srv, "POST", "/api/v1/sessions/ao-1/annotations", payload)
	if status != http.StatusOK {
		t.Fatalf("annotations = %d, want 200; body=%s", status, body)
	}

	var resp struct {
		OK        bool   `json:"ok"`
		SessionID string `json:"sessionId"`
		Delivered string `json:"delivered"`
	}
	mustJSON(t, body, &resp)
	if !resp.OK || resp.SessionID != "ao-1" {
		t.Fatalf("annotation response = %#v", resp)
	}

	// svc.sent is exactly what reached the agent. It must carry the grep-able
	// selector/classes and the user's request, and equal response.delivered.
	for _, want := range []string{"[ui-annotation]", "button.btn.primary", "Save changes", "make this button red"} {
		if !strings.Contains(svc.sent, want) {
			t.Fatalf("message delivered to agent is missing %q:\n%s", want, svc.sent)
		}
	}
	if svc.sent != resp.Delivered {
		t.Fatalf("response.delivered (%q) != message sent to agent (%q)", resp.Delivered, svc.sent)
	}
}

func TestSessionsAPI_AnnotationRequiresSelector(t *testing.T) {
	srv := newSessionTestServer(t, newFakeSessionService())
	body, status, _ := doRequest(t, srv, "POST", "/api/v1/sessions/ao-1/annotations", `{"note":"no selector"}`)
	assertErrorCode(t, body, status, http.StatusBadRequest, "SELECTOR_REQUIRED")
}

func TestSessionsAPI_AnnotationRejectsBadJSON(t *testing.T) {
	srv := newSessionTestServer(t, newFakeSessionService())
	body, status, _ := doRequest(t, srv, "POST", "/api/v1/sessions/ao-1/annotations", `{`)
	assertErrorCode(t, body, status, http.StatusBadRequest, "INVALID_JSON")
}

