import { contextBridge, ipcRenderer } from "electron";

// Preload for the in-app browser's WebContentsView (the previewed page). It is
// deliberately tiny: it lets the injected annotation overlay hand a captured
// element back to the main process, and lets main toggle annotate-mode in the
// page. Nothing else is exposed to the arbitrary URLs loaded here.

contextBridge.exposeInMainWorld("__aoBridge", {
  annotate: (data: unknown): void => {
    ipcRenderer.send("ao:annotation", data);
  },
});

// Main flips annotate-mode; re-broadcast it as a DOM event the overlay listens for.
ipcRenderer.on("ao:annotate-mode", (_event, on: boolean) => {
  window.dispatchEvent(new CustomEvent("ao-annotate-mode", { detail: !!on }));
});

