// overlayScript is injected (via executeJavaScript) into the previewed page's
// WebContentsView after every navigation. In annotate-mode it highlights the
// element under the cursor and, on click, captures a grep-able selector + the
// element's classes/text and hands it to the main process through __aoBridge
// (see browser-preload). The daemon then delivers it to the agent's terminal.
//
// It is a self-contained IIFE string (no bundler touches it); keep it plain ES5-ish.
export const overlayScript = String.raw`
(function () {
  if (window.__aoOverlayInstalled) return;
  window.__aoOverlayInstalled = true;

  var active = false;
  var box = document.createElement('div');
  box.style.cssText = 'position:fixed;z-index:2147483646;pointer-events:none;border:2px solid #4f8cff;background:rgba(79,140,255,0.14);border-radius:3px;display:none;';
  var tag = document.createElement('div');
  tag.style.cssText = 'position:fixed;z-index:2147483647;pointer-events:none;background:#4f8cff;color:#fff;font:11px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;padding:1px 6px;border-radius:3px;display:none;max-width:70vw;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;';

  function ensure() {
    if (!box.parentNode) document.documentElement.appendChild(box);
    if (!tag.parentNode) document.documentElement.appendChild(tag);
  }
  function esc(s) { return window.CSS && CSS.escape ? CSS.escape(s) : s; }
  function cssPath(el) {
    if (!(el instanceof Element)) return '';
    if (el.id) return '#' + esc(el.id);
    var parts = [];
    var cur = el;
    while (cur && cur.nodeType === 1 && parts.length < 5) {
      var sel = cur.tagName.toLowerCase();
      if (cur.classList && cur.classList.length) {
        sel += '.' + Array.prototype.slice.call(cur.classList, 0, 3).map(esc).join('.');
      }
      var parent = cur.parentElement;
      if (parent) {
        var same = Array.prototype.filter.call(parent.children, function (c) { return c.tagName === cur.tagName; });
        if (same.length > 1) sel += ':nth-of-type(' + (Array.prototype.indexOf.call(parent.children, cur) + 1) + ')';
      }
      parts.unshift(sel);
      if (cur.id) break;
      cur = cur.parentElement;
    }
    return parts.join(' > ');
  }
  function label(el) {
    var s = el.tagName.toLowerCase();
    if (el.id) s += '#' + el.id;
    if (el.classList && el.classList.length) s += '.' + Array.prototype.slice.call(el.classList).join('.');
    return s;
  }
  function place(el) {
    var r = el.getBoundingClientRect();
    ensure();
    box.style.display = 'block';
    box.style.left = r.left + 'px'; box.style.top = r.top + 'px';
    box.style.width = r.width + 'px'; box.style.height = r.height + 'px';
    tag.style.display = 'block';
    tag.style.left = r.left + 'px';
    tag.style.top = (r.top - 20 < 0 ? r.bottom + 2 : r.top - 20) + 'px';
    tag.textContent = label(el);
    return r;
  }
  function hide() { box.style.display = 'none'; tag.style.display = 'none'; }

  function onMove(e) {
    if (!active) return;
    var el = e.target;
    if (!el || el === box || el === tag || !(el instanceof Element)) return;
    place(el);
  }
  function onClick(e) {
    if (!active) return;
    e.preventDefault(); e.stopPropagation();
    var el = e.target;
    if (!(el instanceof Element)) return;
    var r = el.getBoundingClientRect();
    var note = window.prompt('What should the agent do with this element?', '');
    if (note === null) return;
    var data = {
      selector: cssPath(el),
      element: label(el),
      text: (el.innerText || el.textContent || '').trim().slice(0, 300),
      url: location.href,
      source: el.getAttribute('data-ao-source') || '',
      note: note,
      rect: { x: Math.round(r.left), y: Math.round(r.top), width: Math.round(r.width), height: Math.round(r.height) }
    };
    try { if (window.__aoBridge && window.__aoBridge.annotate) window.__aoBridge.annotate(data); } catch (err) {}
    var f = document.createElement('div');
    f.style.cssText = 'position:fixed;z-index:2147483647;pointer-events:none;left:' + r.left + 'px;top:' + r.top + 'px;width:' + r.width + 'px;height:' + r.height + 'px;border:2px solid #36c172;background:rgba(54,193,114,0.25);border-radius:3px;';
    document.documentElement.appendChild(f);
    setTimeout(function () { if (f.parentNode) f.parentNode.removeChild(f); }, 450);
  }
  function setActive(on) {
    active = !!on;
    document.documentElement.style.cursor = active ? 'crosshair' : '';
    if (!active) hide();
  }

  window.addEventListener('ao-annotate-mode', function (e) { setActive(e && e.detail); }, true);
  document.addEventListener('mousemove', onMove, true);
  document.addEventListener('click', onClick, true);
  window.addEventListener('scroll', hide, true);
})();
`;

