import { app, BrowserWindow, WebContentsView, ipcMain } from "electron";
import type { WebContents } from "electron";
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import WebSocket from "ws";

import { overlayScript } from "./browser-overlay";

// The Electron main process is the app's thin supervisor: it owns the window
// and is the ONLY layer that talks to the loopback daemon over HTTP. The
// renderer never reaches the network directly — it calls `window.ao.request`,
// which round-trips through the `ao:request` IPC channel below. This keeps the
// daemon loopback-only, sidesteps browser CORS, and matches the repo rule that
// daemon logic must not move into the UI surface.

/** Shape returned to the renderer for every proxied daemon call. */
interface AoResponse {
  ok: boolean;
  status: number;
  data: unknown;
  error?: string;
}

interface AoRequest {
  method: string;
  path: string;
  query?: Record<string, string | number | boolean | undefined>;
  body?: unknown;
}

/**
 * Resolve the daemon base URL. The daemon writes its live pid/port to a
 * handshake file on start (AO_RUN_FILE, defaulting to the user config dir), so
 * we read the port from there and fall back to AO_PORT / 3001. The host is
 * always loopback — the daemon refuses to bind anything else.
 */
function daemonBaseURL(): string {
  const port = discoverPort();
  return `http://127.0.0.1:${port}`;
}

function runFilePath(): string {
  if (process.env.AO_RUN_FILE) return process.env.AO_RUN_FILE;
  const configHome =
    process.env.XDG_CONFIG_HOME || join(homedir(), ".config");
  return join(configHome, "agent-orchestrator", "running.json");
}

function discoverPort(): number {
  try {
    const raw = readFileSync(runFilePath(), "utf8");
    const parsed = JSON.parse(raw) as { port?: number };
    if (parsed.port) return parsed.port;
  } catch {
    // No handshake file yet (daemon not started) — fall through to env/default.
  }
  const envPort = Number(process.env.AO_PORT);
  return Number.isFinite(envPort) && envPort > 0 ? envPort : 3001;
}

function buildURL(base: string, path: string, query?: AoRequest["query"]): string {
  const url = new URL(path.replace(/^\/+/, "/"), base);
  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value !== undefined) url.searchParams.set(key, String(value));
    }
  }
  return url.toString();
}

async function proxyToDaemon(req: AoRequest): Promise<AoResponse> {
  const base = daemonBaseURL();
  const url = buildURL(base, req.path, req.query);
  try {
    const res = await fetch(url, {
      method: req.method,
      headers: req.body ? { "Content-Type": "application/json" } : undefined,
      body: req.body ? JSON.stringify(req.body) : undefined,
    });
    const text = await res.text();
    const data = text ? safeJSON(text) : null;
    return { ok: res.ok, status: res.status, data };
  } catch (err) {
    // Connection refused etc. — the daemon is almost certainly not running.
    return {
      ok: false,
      status: 0,
      data: null,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

function safeJSON(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

let mainWindow: BrowserWindow | null = null;

function createWindow(): void {
  const window = new BrowserWindow({
    width: 1280,
    height: 860,
    minWidth: 900,
    minHeight: 600,
    backgroundColor: "#0b0d12",
    title: "ReverbCode",
    webPreferences: {
      preload: join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });
  mainWindow = window;
  window.on("closed", () => {
    mainWindow = null;
    browserView = null;
  });

  const devServer = process.env.VITE_DEV_SERVER_URL;
  if (devServer) {
    void window.loadURL(devServer);
    window.webContents.openDevTools({ mode: "detach" });
  } else {
    void window.loadFile(join(__dirname, "renderer", "index.html"));
  }
}

// --- in-app browser (WebContentsView) ----------------------------------------
//
// The previewed page lives in its own WebContentsView, a native overlay
// composited over the React renderer at pixel bounds the renderer reports. Its
// webContents lives here in main, so we can inject the annotation overlay and
// (later) drive it for the agent. See docs/design/in-app-browser.md.

let browserView: WebContentsView | null = null;

interface BrowserMsg {
  type:
    | "navigate"
    | "setBounds"
    | "hide"
    | "back"
    | "forward"
    | "reload"
    | "setAnnotateMode"
    | "destroy";
  url?: string;
  bounds?: { x: number; y: number; width: number; height: number };
  on?: boolean;
}

function normalizeURL(raw: string): string {
  const u = raw.trim();
  if (/^https?:\/\//i.test(u)) return u;
  return "http://" + u;
}

function ensureBrowserView(win: BrowserWindow): WebContentsView {
  if (browserView && !browserView.webContents.isDestroyed()) return browserView;
  const view = new WebContentsView({
    webPreferences: {
      preload: join(__dirname, "browser-preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
    },
  });
  win.contentView.addChildView(view);
  view.setVisible(false);

  const wc = view.webContents;
  const inject = (): void => {
    void wc.executeJavaScript(overlayScript).catch(() => {});
  };
  const emit = (): void => {
    if (win.isDestroyed()) return;
    win.webContents.send("ao:browser-state", {
      url: wc.getURL(),
      title: wc.getTitle(),
      canGoBack: wc.navigationHistory.canGoBack(),
      canGoForward: wc.navigationHistory.canGoForward(),
      loading: wc.isLoadingMainFrame(),
    });
  };
  wc.on("did-finish-load", () => {
    inject();
    emit();
  });
  wc.on("did-navigate", () => {
    inject();
    emit();
  });
  wc.on("did-navigate-in-page", emit);
  wc.on("did-start-loading", emit);
  wc.on("did-stop-loading", emit);

  browserView = view;
  return view;
}

function handleBrowser(msg: BrowserMsg): void {
  const win = mainWindow;
  if (!win || win.isDestroyed()) return;
  if (msg.type === "destroy") {
    if (browserView) {
      win.contentView.removeChildView(browserView);
      browserView = null;
    }
    return;
  }
  const view = ensureBrowserView(win);
  const wc = view.webContents;
  switch (msg.type) {
    case "navigate":
      if (msg.url) void wc.loadURL(normalizeURL(msg.url)).catch(() => {});
      break;
    case "setBounds":
      if (msg.bounds) {
        view.setBounds(msg.bounds);
        view.setVisible(true);
      }
      break;
    case "hide":
      view.setVisible(false);
      break;
    case "back":
      if (wc.navigationHistory.canGoBack()) wc.navigationHistory.goBack();
      break;
    case "forward":
      if (wc.navigationHistory.canGoForward()) wc.navigationHistory.goForward();
      break;
    case "reload":
      wc.reload();
      break;
    case "setAnnotateMode":
      wc.send("ao:annotate-mode", !!msg.on);
      break;
  }
}

app.whenReady().then(() => {
  ipcMain.handle("ao:request", (_event, req: AoRequest) => proxyToDaemon(req));
  ipcMain.handle("ao:browser", (_event, msg: BrowserMsg) => handleBrowser(msg));
  // The annotation overlay (running in the WebContentsView) hands a captured
  // element to main; forward it to the React renderer, which owns the session id
  // and POSTs it to the daemon.
  ipcMain.on("ao:annotation", (_event, data: unknown) => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send("ao:browser-annotation", data);
    }
  });

  createWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    app.quit();
  }
});

