import { contextBridge, ipcRenderer } from "electron";

// The preload is the ONLY bridge between the sandboxed renderer and the main
// process. It exposes a single typed `request` that forwards to the `ao:request`
// IPC channel (which proxies to the loopback daemon). The renderer therefore
// never sees `ipcRenderer` or the network directly — it just awaits `window.ao`.

export interface AoRequest {
  method: string;
  path: string;
  query?: Record<string, string | number | boolean | undefined>;
  body?: unknown;
}

export interface AoResponse<T = unknown> {
  ok: boolean;
  status: number;
  data: T;
  error?: string;
}

export interface BrowserControlMsg {
  type:
    | "navigate"
    | "setBounds"
    | "hide"
    | "back"
    | "forward"
    | "reload"
    | "setAnnotateMode"
    | "destroy";
  url?: string;
  bounds?: { x: number; y: number; width: number; height: number };
  on?: boolean;
}

export interface BrowserState {
  url: string;
  title: string;
  canGoBack: boolean;
  canGoForward: boolean;
  loading: boolean;
}

const api = {
  request: <T = unknown>(req: AoRequest): Promise<AoResponse<T>> =>
    ipcRenderer.invoke("ao:request", req),

  // The in-app browser (a native WebContentsView owned by main). The renderer
  // drives it by id-less control messages and subscribes to nav-state +
  // annotation events.
  browser: {
    control: (msg: BrowserControlMsg): Promise<void> =>
      ipcRenderer.invoke("ao:browser", msg),
    onState: (cb: (state: BrowserState) => void): (() => void) => {
      const listener = (_e: unknown, s: BrowserState): void => cb(s);
      ipcRenderer.on("ao:browser-state", listener);
      return () => ipcRenderer.removeListener("ao:browser-state", listener);
    },
    onAnnotation: (cb: (data: unknown) => void): (() => void) => {
      const listener = (_e: unknown, d: unknown): void => cb(d);
      ipcRenderer.on("ao:browser-annotation", listener);
      return () => ipcRenderer.removeListener("ao:browser-annotation", listener);
    },
  },
};

contextBridge.exposeInMainWorld("ao", api);

export type AoBridge = typeof api;

