            {statusMeta(s.status).label}
          </span>
        )}
        <div className="tr-tabs">
          <button
            className={tab === "terminal" ? "canvas-tab active" : "canvas-tab"}
            onClick={() => setTab("terminal")}
          >
            Terminal
          </button>
          <button
            className={tab === "browser" ? "canvas-tab active" : "canvas-tab"}
            onClick={() => setTab("browser")}
          >
            Browser
          </button>
        </div>
        <div className="spacer" />
        {s?.harness && <span className="tr-meta mono">{s.harness}</span>}
        {s && !s.isTerminated && (
          <button
            className="btn-ghost sm danger"
            disabled={busy}
            onClick={async () => {
              setBusy(true);
              try {
                await killSession(props.sessionId);
                await refresh();
                await props.onChanged();
              } catch (err) {
                props.onError(err instanceof Error ? err.message : String(err));
              } finally {
                setBusy(false);
              }
            }}
          >
            {busy ? <span className="spinner" /> : "Kill"}
          </button>
        )}
      </header>

      <div className="tr-body">
        {tab === "terminal" ? (
          <Terminal
            sessionId={props.sessionId}
            handleId={s?.metadata?.runtimeHandleId}
            connected={connected}
          />
        ) : (
          <BrowserPane sessionId={props.sessionId} onError={props.onError} />
        )}
      </div>
    </div>
  );
}

