import { useEffect, useRef } from "react";
import { Terminal as Xterm } from "@xterm/xterm";
import { FitAddon } from "@xterm/addon-fit";

/*
 * Terminal — xterm view over the daemon's WebSocket terminal mux.
 *
 * The renderer is sandboxed and never opens the socket itself. It talks to the
 * Electron main process through `window.ao.mux` (see src/preload.ts), which
 * relays JSON frames to/from  ws://127.0.0.1:<port>/mux  in the main process
 * (see src/main.ts). Protocol: backend/internal/terminal/protocol.go.
 *
 * The mux is keyed by the session's RUNTIME HANDLE id (the pane handle), NOT the
 * session id. That handle is `session.metadata.runtimeHandleId` on the backend,
 * but it is currently `json:"-"` on the session DTO, so it is not exposed over
 * the REST surface yet (gap noted to the maintainer). Until it is exposed, this
 * component treats `props.sessionId` as the handle so the wiring is complete and
 * will work unchanged once the field is surfaced — swap to the real handle prop
 * at that point.
 */

export interface TerminalProps {
  /** The session whose PTY pane to attach to. */
  sessionId: string;
  /** Drives the header status dot. */
  connected?: boolean;
  /**
   * The runtime handle id (pane handle) the mux `open` expects. Falls back to
   * `sessionId` until the backend surfaces `metadata.runtimeHandleId` on the
   * session DTO.
   */
  handleId?: string;
}

export function Terminal(props: TerminalProps) {
  const { sessionId, connected, handleId } = props;
  const mountRef = useRef<HTMLDivElement>(null);
  // The mux open key. Once the DTO exposes the runtime handle, pass it as
  // `handleId`; until then we attach by sessionId.
  const paneId = handleId ?? sessionId;

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;

    const term = new Xterm({
      convertEol: true,
      cursorBlink: true,
      fontSize: 13,
      lineHeight: 1.2,
      scrollback: 100_000,
      allowProposedApi: true,
      fontFamily:
        'ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace',
      theme: {
        background: "#0b0d12",
        foreground: "#d6dae3",
        cursor: "#8ab4f8",
      },
    });

    const fit = new FitAddon();
    term.loadAddon(fit);
    term.open(mount);

    // Disposed flag guards async callbacks (RAF / IPC) that may fire after the
    // effect cleanup has already torn the terminal down.
    let disposed = false;

    const safeFit = (): void => {
      if (disposed) return;
      try {
        fit.fit();
      } catch {
        // fit throws if the element has zero size (not yet laid out); ignore.
      }
    };
    safeFit();

    // Attach to the pane and push the initial size once the socket is open.
    const mux = window.ao.mux;
    void mux
      .open(paneId)
      .then(() => {
        if (disposed) return;
        safeFit();
        return mux.resize(paneId, term.cols, term.rows);
      })
      .catch(() => {
        // Surface a connection failure inside the terminal rather than silently.
        if (!disposed) term.write("\r\n\x1b[31m[mux] failed to attach to pane\x1b[0m\r\n");
      });

    // Server → term: base64 PTY output is decoded to bytes and written raw.
    const offData = mux.onData(paneId, (b64: string) => {
      if (disposed) return;
      term.write(base64ToBytes(b64));
    });

    // Server → term: pane exited.
    const offExit = mux.onExit(paneId, () => {
      if (disposed) return;
      term.write("\r\n\x1b[2m[process exited]\x1b[0m\r\n");
    });

    // term → server: keystrokes are base64-encoded.
    const onDataDisposable = term.onData((data: string) => {
      void mux.send(paneId, bytesToBase64(stringToBytes(data)));
    });

    // Keep the PTY geometry in sync with the visible element.
    let lastCols = term.cols;
    let lastRows = term.rows;
    const ro = new ResizeObserver(() => {
      if (disposed) return;
      safeFit();
      if (term.cols !== lastCols || term.rows !== lastRows) {
        lastCols = term.cols;
        lastRows = term.rows;
        void mux.resize(paneId, term.cols, term.rows);
      }
    });
    ro.observe(mount);

    return () => {
      disposed = true;
      ro.disconnect();
      offData();
      offExit();
      onDataDisposable.dispose();
      void mux.close(paneId);
      term.dispose();
    };
  }, [paneId]);

  return (
    <div className="terminal">
      <div className="terminal-head">
        <span className={`term-dot ${connected ? "on" : ""}`} />
        <span className="term-title">terminal</span>
        <span className="term-session">{sessionId}</span>
      </div>
      <div ref={mountRef} className="terminal-body" data-session={sessionId} />
    </div>
  );
}

// ── base64 ⇆ bytes (no Node Buffer in the sandboxed renderer) ───────────────

function base64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function bytesToBase64(bytes: Uint8Array): string {
  let bin = "";
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

function stringToBytes(s: string): Uint8Array {
  return new TextEncoder().encode(s);
}

