  animation: pulse-dot 2s ease-in-out infinite;
}
.term-title { font-family: var(--font-mono); font-size: 11px; color: var(--fg-muted); }
.term-session { font-family: var(--font-mono); font-size: 10px; color: var(--fg-dim); margin-left: auto; }
.terminal-body { flex: 1; min-height: 0; overflow: auto; padding: 12px 14px; }
