import { useCallback, useEffect, useState } from "react";
import { getSession, killSession, statusMeta, type Session } from "../lib/api";
import { Terminal } from "./Terminal";
import { BrowserPane } from "./BrowserPane";
import {
  ResizablePanelGroup,
  ResizablePanel,
  ResizableHandle,
} from "./ui/resizable";

// TerminalView is the full-screen session workspace (its own route, not the old
// cramped detail overlay): a slim header (back, title, status, kill) over a
// horizontal split with the live agent Terminal on the left and the in-app
// Browser on the right, draggable via the shadcn Resizable handle. The terminal
// is interactive, so you type to the agent directly — no separate send box.
export function TerminalView(props: {
  sessionId: string;
  fallback: Session | null;
  onClose: () => void;
  onChanged: () => Promise<void> | void;
  onError: (msg: string) => void;
}) {
  const [session, setSession] = useState<Session | null>(props.fallback);
  const [busy, setBusy] = useState(false);

  const refresh = useCallback(async () => {
    try {
      setSession(await getSession(props.sessionId));
    } catch (err) {
      props.onError(err instanceof Error ? err.message : String(err));
    }
  }, [props]);

  useEffect(() => {
    void refresh();
    const id = window.setInterval(() => void refresh(), 2000);
    return () => window.clearInterval(id);
  }, [refresh]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") props.onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [props]);

  const s = session;
  const title = s?.displayName || s?.id || props.sessionId;
  const connected = !!s && !s.isTerminated && s.activity?.state === "active";

  return (
    <div className="terminal-route">
      <header className="tr-bar">
        <button className="icon-btn" onClick={props.onClose} title="Back (Esc)">
          ←
        </button>
        <h3 className="tr-title">{title}</h3>
        {s && (
          <span className={`badge tone-${statusMeta(s.status).tone}`}>
            <span className="bdot" />
            {statusMeta(s.status).label}
          </span>
        )}
        <div className="spacer" />
        {s?.harness && <span className="tr-meta mono">{s.harness}</span>}
        {s && !s.isTerminated && (
          <button
            className="btn-ghost sm danger"
            disabled={busy}
            onClick={async () => {
              setBusy(true);
              try {
                await killSession(props.sessionId);
                await refresh();
                await props.onChanged();
              } catch (err) {
                props.onError(err instanceof Error ? err.message : String(err));
              } finally {
                setBusy(false);
              }
            }}
          >
            {busy ? <span className="spinner" /> : "Kill"}
          </button>
        )}
      </header>

      <div className="tr-body">
        <ResizablePanelGroup direction="horizontal" autoSaveId="tr-split">
          <ResizablePanel
            defaultSize={55}
            minSize={25}
            className="flex min-h-0 min-w-0 overflow-hidden"
          >
            <Terminal
              sessionId={props.sessionId}
              handleId={s?.metadata?.runtimeHandleId}
              connected={connected}
            />
          </ResizablePanel>
          <ResizableHandle withHandle />
          <ResizablePanel
            defaultSize={45}
            minSize={25}
            className="flex min-h-0 min-w-0 overflow-hidden"
          >
            <BrowserPane sessionId={props.sessionId} onError={props.onError} />
          </ResizablePanel>
        </ResizablePanelGroup>
      </div>
    </div>
  );
}

