/* No outer scroll/padding: xterm owns scrolling via its own .xterm-viewport.
   An outer overflow:auto created a second scroll container that swallowed the
   wheel before it reached xterm (and padding offset its mouse coordinates). */
.terminal-body { flex: 1; min-height: 0; overflow: hidden; padding: 6px 8px; }
.terminal-body .xterm,
.terminal-body .xterm-viewport { height: 100%; }

