// Keep the PTY geometry in sync with the visible element — but DEBOUNCED.
// Dragging the split fires ResizeObserver continuously; sending a resize per
// frame would make the streamed zellij client re-render dozens of times and
// pile up garbled redraws. Refit locally each frame (cheap, no PTY traffic),
// but only push the resize to the PTY once the drag settles (120ms idle).
let lastCols = term.cols;
let lastRows = term.rows;
let resizeTimer: number | undefined;
const ro = new ResizeObserver(() => {
  if (disposed) return;
  safeFit();
  if (term.cols === lastCols && term.rows === lastRows) return;
  if (resizeTimer) window.clearTimeout(resizeTimer);
  resizeTimer = window.setTimeout(() => {
    if (disposed) return;
    lastCols = term.cols;
    lastRows = term.rows;
    void mux.resize(paneId, term.cols, term.rows);
  }, 120);
});
ro.observe(mount);

return () => {
  disposed = true;
  if (resizeTimer) window.clearTimeout(resizeTimer);
  ro.disconnect();
  offData();
  offExit();
  onDataDisposable.dispose();
  void mux.close(paneId);
  term.dispose();
};

