func attachArgs(id string) []string {
	// Attach with pane frames OFF. The in-app terminal streams this attach client
	// to xterm, and a pane frame is a bordered title bar ("agent ─────") that the
	// client repaints on every resize — those repaints stack into garbled lines.
	// --pane-frames false is set at session creation too, but the attaching client
	// re-enables frames unless told otherwise. A single-pane session needs no frame.
	return []string{"attach", id, "options", "--pane-frames", "false"}
}

