// The in-app browser is a native WebContentsView owned HERE in main, not by the
// React tree. On a renderer reload (⌘R, or a Vite full reload after an HMR
// change) React is torn down WITHOUT running BrowserPane's unmount cleanup, so
// the view would be left orphaned and visible — floating over the fresh UI with
// nothing able to hide it. Tear it down whenever the main frame starts loading;
// the next renderer re-creates it on demand via ensureBrowserView. (Fires on the
// initial load too, where browserView is null and this is a no-op.)
window.webContents.on("did-start-loading", () => {
  if (!browserView) return;
  try {
    window.contentView.removeChildView(browserView);
  } catch {
    /* window may be mid-teardown */
  }
  if (!browserView.webContents.isDestroyed()) {
    try {
      browserView.webContents.close();
    } catch {
      /* ignore */
    }
  }
  browserView = null;
});

